#include <cstdio>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

class HungarianAlgorithm {
public:
    static const int MAX_SIZE = 2000;
    int matchCount, matchPos[MAX_SIZE], matchRev[MAX_SIZE];
    int maxMatching(int n, vector<int> adj[]) {
        matchCount = 0;
        memset(matchPos, -1, sizeof(matchPos));
        memset(matchRev, -1, sizeof(matchRev));
        for (int i = 0; i < n; i++) {
            memset(visited, 0, sizeof(visited));
            if (tryMatch(i, adj)) matchCount++;
        }
        return matchCount;
    }
private:
    int visited[MAX_SIZE];
    bool tryMatch(int u, vector<int> adj[]) {
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = 1;
                if (matchRev[v] < 0 || tryMatch(matchRev[v], adj)) {
                    matchPos[u] = v;
                    matchRev[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
};

const int INF = 1000000000;
const int dirR[] = {0, -1, 0, 1};
const int dirC[] = {1, 0, -1, 0};
int gridA[12][12], gridB[12][12], distF[12][12], sizeN, timeT;
vector<int> edges[2000], cellGroups[12][12];

void floodFill(int startR, int startC) {
    queue<int> qRow, qCol;
    memset(distF, -1, sizeof(distF));
    qRow.push(startR);
    qCol.push(startC);
    distF[startR][startC] = 0;
    while (!qRow.empty()) {
        int r = qRow.front(); qRow.pop();
        int c_ = qCol.front(); qCol.pop();
        for (int i = 0; i < 4; i++) {
            int nr = r + dirR[i], nc = c_ + dirC[i];
            if (gridA[nr][nc] >= 0 && distF[nr][nc] < 0) {
                distF[nr][nc] = distF[r][c_] + 1;
                qRow.push(nr);
                qCol.push(nc);
            }
        }
    }
}

void assignMarks(int r, int c, int count) {
    int visitedV[12][12];
    queue<int> qRow, qCol;
    memset(visitedV, -1, sizeof(visitedV));
    qRow.push(r);
    qCol.push(c);
    visitedV[r][c] = 0;
    while (!qRow.empty()) {
        int rr = qRow.front(); qRow.pop();
        int cc = qCol.front(); qCol.pop();
        if (visitedV[rr][cc] > min(timeT, distF[rr][cc])) continue;
        for (int groupIdx : cellGroups[rr][cc]) {
            for (int i = 0; i < count; i++) edges[sizeN + i].push_back(groupIdx);
        }
        if (visitedV[rr][cc] == min(timeT, distF[rr][cc])) continue;
        for (int i = 0; i < 4; i++) {
            int nr = rr + dirR[i], nc = cc + dirC[i];
            if (gridA[nr][nc] >= 0 && visitedV[nr][nc] < 0) {
                visitedV[nr][nc] = visitedV[rr][cc] + 1;
                qRow.push(nr);
                qCol.push(nc);
            }
        }
    }
    sizeN += count;
}

int main() {
    int totalNodes = 0, totalEdges = 0, startR, startC;
    scanf("%d%d", &n, &t);
    memset(gridA, -1, sizeof(gridA));
    memset(gridB, -1, sizeof(gridB));
    for (int i = 1; i <= n; i++) {
        getchar();
        for (int j = 1; j <= n; j++) {
            char ch = getchar();
            if (ch >= '0' && ch <= '9') gridA[i][j] = ch - '0';
            if (ch == 'Z') {
                startR = i;
                startC = j;
            }
        }
    }
    floodFill(startR, startC);
    getchar();
    for (int i = 1; i <= n; i++) {
        getchar();
        for (int j = 1; j <= n; j++) {
            char ch = getchar();
            if (ch >= '0' && ch <= '9') gridB[i][j] = ch - '0';
            for (int k = 0; k < gridB[i][j]; k++) cellGroups[i][j].push_back(totalEdges++);
        }
    }
    for (int i = 1; i <= n; i++) for (int j = 1; j <= n; j++) if (distF[i][j] < 0) distF[i][j] = INF;
    for (int i = 1; i <= n; i++) for (int j = 1; j <= n; j++) if (gridA[i][j] > 0) assignMarks(i, j, gridA[i][j]);
    HungarianAlgorithm matcher;
    printf("%d\n", matcher.maxMatching(totalNodes, edges));
    return 0;
}
